const argon2 = require('argon2');

const hash = await argon2.hash(password, {
  type: argon2.argon2id,
  memoryCost: 19456, // in KiB = 19 MiB
  timeCost: 2,
  parallelism: 1,
});
const ok = await argon2.verify(hash, password);

const claims = jwt.verify(token, publicKey, {
  algorithms: ['RS256'],
  issuer: 'https://auth.example.com',
  audience: 'orders-api',
}); // verifies signature, iss, aud and exp (if present); throws on failure
if (typeof claims.exp !== 'number') throw new Error('missing exp');
// never use jwt.decode() to authenticate: it does not verify the signature

// allowlist: a-z 0-9 _, 3-20 characters long
const USERNAME = /^[a-z0-9_]{3,20}$/;
if (typeof body.username !== 'string' || !USERNAME.test(body.username)) {
  return res.status(400).json({ error: 'invalid_username' });
}
// semantic: also check the business meaning (dates must parse, and start must not be after end)
const start = Date.parse(body.start);
const end = Date.parse(body.end);
if (Number.isNaN(start) || Number.isNaN(end) || start > end) {
  return res.status(400).json({ error: 'invalid_range' });
}

// after the password check succeeds: issue a new session ID before storing userId
req.session.regenerate((err) => {
  if (err) return next(err);
  req.session.userId = user.id;
  res.redirect('/');
});

// logout: destroy the session on the server, then clear the cookie
req.session.destroy(() => {
  res.clearCookie('connect.sid').redirect('/login');
});

