// fail open: the permission check crashes but the request still gets through
try { await assertCanView(req.user, doc); } catch (e) { log(e); }
next();

// fail closed: crash or failed check = deny
try { await assertCanView(req.user, doc); }
catch (e) { log(e); return res.sendStatus(403); }
next();

// Risky: fetches whatever URL the user sent
