// Safer: accept only a key and map it to an allowed destination
const HOSTS = { github: 'https://api.github.com' };
const base = HOSTS[req.body.provider];
if (!base) return res.sendStatus(400);
const r = await fetch(`${base}/zen`, { redirect: 'error' });

// Risky: if the user also sends {"role":"admin"}, it gets saved
await User.update(req.user.id, req.body);

// Safe: pick only the allowed fields
const { displayName, bio } = req.body;
await User.update(req.user.id, { displayName, bio });

const nonce = crypto.randomUUID(); // fresh for every response
res.setHeader('Content-Security-Policy', `script-src 'nonce-${nonce}'`);
res.send(`<script nonce="${nonce}" src="/main.js"></script>`);

